SELECT id, customer_id, browser, country, FIRST_VALUE(browser) IGNORE NULLS OVER (PARTITION BY device ORDER BY started_at, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS first_known_browser, FIRST_VALUE(browser, TRUE) OVER (PARTITION BY browser, country ORDER BY started_at, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS first_known_browser_2, ROW_NUMBER() OVER (PARTITION BY browser, device ORDER BY started_at, id) AS event_seq FROM sessions
